# १ तः १० पर्यन्तम् गणय
आवर्तय i = १ तः १० पर्यन्तम् {
  वद i
}

मान वयः = १८

यदि वयः >= १८ {
  वद "त्वं मतदानं कर्तुं शक्नोषि।"
} अन्यथा {
  वद "प्रतीक्षस्व।"
}

# सप्तानां पाटी (table of 7)
मान अङ्कः = ७
आवर्तय i = १ तः १० पर्यन्तम् {
  वद अङ्कः, "×", i, "=", अङ्कः * i
}

# a function that calls itself
कार्यम् क्रमगुणितम्(क) {
  यदि क <= १ { प्रत्यर्पय १ }
  प्रत्यर्पय क * क्रमगुणितम्(क - १)
}

आवर्तय i = १ तः ८ पर्यन्तम् {
  वद i, "! =", क्रमगुणितम्(i)
}

# Pingala's मेरुप्रस्तार: each number is the sum of the two above it
मान पङ्क्तिः = [१]
आवर्तय i = १ तः ७ पर्यन्तम् {
  वद पङ्क्तिः
  मान नवा = [१]
  आवर्तय j = २ तः दैर्घ्यम्(पङ्क्तिः) पर्यन्तम् {
    योजय(नवा, पङ्क्तिः[j - १] + पङ्क्तिः[j])
  }
  योजय(नवा, १)
  पङ्क्तिः = नवा
}

# Lilavati: a peacock sits on a pillar ९ hastas tall.
# A snake, २७ hastas away, heads for its hole at the foot.
# The peacock swoops and both travel the same distance.
# How far from the hole is the snake caught?
मान स्तम्भः = ९
मान दूरम् = २७
आवर्तय क = ० तः दूरम् पर्यन्तम् {
  # snake travels (दूरम् - क), peacock flies the slant line
  यदि (दूरम् - क) ^ २ == क ^ २ + स्तम्भः ^ २ {
    वद "सर्पः छिद्रात्", क, "हस्तेषु गृहीतः।"
    वद "(The snake is caught", क, "hastas from the hole.)"
  }
}

# अभाज्य संख्याः (primes) up to ५०
कार्यम् अभाज्यः(क) {
  यदि क < २ { प्रत्यर्पय असत्यम् }
  मान भ = २
  यावत् भ * भ <= क {
    यदि क % भ == ० { प्रत्यर्पय असत्यम् }
    भ = भ + १
  }
  प्रत्यर्पय सत्यम्
}
मान फलम् = []
आवर्तय i = १ तः ५० पर्यन्तम् {
  यदि अभाज्यः(i) { योजय(फलम्, i) }
}
वद फलम्

मान देवाः = ["शिवः", "विष्णुः", "देवी", "गणेशः"]
प्रत्येकम् देवः अस्मिन् देवाः {
  वद "ॐ", देवः, "नमः"
}
वद "सङ्ख्या:", दैर्घ्यम्(देवाः)
